/**
 * Statistics for the bake-off report (plan section 7.3).
 *
 * Three things the report needs and nothing else: a bootstrap confidence
 * interval for every rate, a paired test between two architectures measured on
 * the same items, and the rule-of-three upper bound that keeps a "zero wrong
 * autos" claim honest.
 *
 * Every resample is driven by a seeded generator, so a report can be
 * regenerated byte for byte from its config.
 */

export interface Interval {
  /** The point estimate the interval brackets. */
  mean: number;
  /** Lower bound, at the requested alpha. */
  lo: number;
  /** Upper bound, at the requested alpha. */
  hi: number;
}

/** Small, fast, seedable PRNG (mulberry32). Deterministic across platforms. */
export function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Linear-interpolated percentile of an ascending array. */
export function percentile(ascending: number[], p: number): number {
  if (ascending.length === 0) return Number.NaN;
  if (ascending.length === 1) return ascending[0];
  const position = p * (ascending.length - 1);
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return ascending[lower];
  return ascending[lower] + (position - lower) * (ascending[upper] - ascending[lower]);
}

export interface BootstrapOptions {
  /** Resamples. Plan start value is 10,000. */
  resamples?: number;
  /** Seed, so a rerun reproduces the interval. */
  seed?: number;
  /** Two-sided alpha; 0.05 gives a 95% interval. */
  alpha?: number;
}

/**
 * Percentile bootstrap over a flat list of per-item values.
 *
 * Values are usually 0/1 per item, so the mean is a rate, but any per-item
 * number works.
 */
export function bootstrapCI(values: number[], options: BootstrapOptions = {}): Interval {
  const resamples = options.resamples ?? 10_000;
  const alpha = options.alpha ?? 0.05;
  if (values.length === 0) return { mean: Number.NaN, lo: Number.NaN, hi: Number.NaN };

  const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
  if (values.length === 1) return { mean, lo: mean, hi: mean };

  const random = mulberry32(options.seed ?? 1);
  const means: number[] = new Array(resamples);
  for (let r = 0; r < resamples; r += 1) {
    let sum = 0;
    for (let i = 0; i < values.length; i += 1) sum += values[Math.floor(random() * values.length)];
    means[r] = sum / values.length;
  }
  means.sort((a, b) => a - b);
  return { mean, lo: percentile(means, alpha / 2), hi: percentile(means, 1 - alpha / 2) };
}

/**
 * Bootstrap that resamples inside each stratum and pools afterwards.
 *
 * The plan stratifies by speaker: drawing whole speakers would answer a
 * different question, and drawing across speakers would ignore that one
 * speaker's utterances are correlated. Resampling within each stratum and
 * pooling keeps every stratum's weight fixed.
 */
export function bootstrapCIStratified(strata: number[][], options: BootstrapOptions = {}): Interval {
  const present = strata.filter((stratum) => stratum.length > 0);
  if (present.length === 0) return { mean: Number.NaN, lo: Number.NaN, hi: Number.NaN };

  const all = present.flat();
  const mean = all.reduce((sum, value) => sum + value, 0) / all.length;
  if (present.length === 1 && present[0].length === 1) return { mean, lo: mean, hi: mean };

  const resamples = options.resamples ?? 10_000;
  const alpha = options.alpha ?? 0.05;
  const random = mulberry32(options.seed ?? 1);
  const means: number[] = new Array(resamples);
  for (let r = 0; r < resamples; r += 1) {
    let sum = 0;
    let count = 0;
    for (const stratum of present) {
      for (let i = 0; i < stratum.length; i += 1) sum += stratum[Math.floor(random() * stratum.length)];
      count += stratum.length;
    }
    means[r] = sum / count;
  }
  means.sort((a, b) => a - b);
  return { mean, lo: percentile(means, alpha / 2), hi: percentile(means, 1 - alpha / 2) };
}

/**
 * The 95% upper bound on a rate when zero events were observed in `n` trials.
 *
 * Claiming FAR <= 1% needs at least 300 auto decisions, because 3/300 = 1%.
 * Below that the report must state the bound rather than the claim.
 */
export function ruleOfThree(n: number): number {
  return n > 0 ? 3 / n : Number.NaN;
}

/** Exact two-sided McNemar p-value for a paired comparison. */
export function mcnemarExact(discordantA: number, discordantB: number): number {
  const n = discordantA + discordantB;
  if (n === 0) return 1;

  // Sum of the lower binomial tail by recurrence, so no gamma function is needed.
  const k = Math.min(discordantA, discordantB);
  let term = Math.pow(0.5, n); // C(n, 0) * 0.5^n
  let tail = term;
  for (let i = 1; i <= k; i += 1) {
    term = (term * (n - i + 1)) / i;
    tail += term;
  }
  return Math.min(1, 2 * tail);
}

/**
 * Paired comparison of two architectures on the same items (McNemar).
 *
 * `a` and `b` are per-item correctness, aligned by item. Returns the two
 * discordant counts and the exact two-sided p-value.
 */
export function mcnemar(a: boolean[], b: boolean[]): { b: number; c: number; p: number } {
  if (a.length !== b.length) throw new Error('mcnemar needs two equally long, aligned series');
  let onlyA = 0;
  let onlyB = 0;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] && !b[i]) onlyA += 1;
    else if (!a[i] && b[i]) onlyB += 1;
  }
  return { b: onlyA, c: onlyB, p: mcnemarExact(onlyA, onlyB) };
}

/**
 * Paired bootstrap of the difference `a - b` over aligned per-item values.
 *
 * Used by the optimization loop's accept rule, which moves best-so-far only
 * when the interval of the difference excludes zero.
 */
export function bootstrapDifference(
  a: number[],
  b: number[],
  options: BootstrapOptions = {},
): Interval & { excludesZero: boolean } {
  if (a.length !== b.length) throw new Error('bootstrapDifference needs two equally long, aligned series');
  const resamples = options.resamples ?? 10_000;
  const alpha = options.alpha ?? 0.05;
  const n = a.length;
  if (n === 0) return { mean: Number.NaN, lo: Number.NaN, hi: Number.NaN, excludesZero: false };

  const observed = a.reduce((sum, value, i) => sum + (value - b[i]), 0) / n;
  const random = mulberry32(options.seed ?? 1);
  const diffs: number[] = new Array(resamples);
  for (let r = 0; r < resamples; r += 1) {
    let sum = 0;
    for (let i = 0; i < n; i += 1) {
      const index = Math.floor(random() * n);
      sum += a[index] - b[index];
    }
    diffs[r] = sum / n;
  }
  diffs.sort((x, y) => x - y);
  const lo = percentile(diffs, alpha / 2);
  const hi = percentile(diffs, 1 - alpha / 2);
  return { mean: observed, lo, hi, excludesZero: lo > 0 || hi < 0 };
}
